// Split vendors array into individual items for processing
const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || [];

if (!vendors.length) {
  return [{ json: { _no_vendors: true } }];
}

return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || '',
    website: (v.website || '').replace(/\/$/, ''),
  }
}));

// Content quality gate: count visible words in response body
// Pass-through all upstream fields; add quality gate flags

const item = $input.first().json;

// Strip HTML tags to count visible text words
const body = String(item.$response?.body || item.body || '');
const visibleText = body
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const wordCount = visibleText ? visibleText.split(' ').filter(w => w.length > 1).length : 0;
const statusCode = item.$response?.statusCode || item.statusCode || 0;
const hasEnoughContent = wordCount >= 200 && statusCode < 400;

return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    pricing_url: `${item.website}/pricing`,
    status_code: statusCode,
    word_count: wordCount,
    has_enough_content: hasEnoughContent,
    visible_text: visibleText.slice(0, 8000),
  }
}];

// Extract pricing tiers from scraped text using regex heuristics
const item = $input.first().json;
const text = item.visible_text || '';

// Common pricing tier patterns
const tierPatterns = [
  /\b(free|starter|basic|professional|pro|business|enterprise|growth|scale|team|plus|premium|ultimate)\b/gi,
];

const tiers = new Set();
for (const pattern of tierPatterns) {
  const matches = text.matchAll(pattern);
  for (const m of matches) {
    const t = m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
    tiers.add(t);
  }
}

// Detect free trial signals
const hasFreeTrialSignal = /free trial|try free|\d+.day free|no credit card/i.test(text);

// Pricing array: de-duped tier names, max 8
const pricingTiers = [...tiers].slice(0, 8);

return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    has_public_pricing_page: true,
    pricing: pricingTiers,
    free_trial: hasFreeTrialSignal,
    pricing_source: 'scraped',
  }
}];

