// Parse OpenAI response and normalise to write contract
const item = $input.first().json;

let extracted = {};
try {
  const content = item.choices?.[0]?.message?.content || '{}';
  extracted = JSON.parse(content);
} catch (e) {
  // leave extracted empty
}

return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    has_public_pricing_page: extracted.has_public_pricing_page ?? false,
    pricing: extracted.pricing || [],
    free_trial: extracted.free_trial ?? null,
    pricing_source: 'llm_inferred',
  }
}];
